      en: ["The name translates to crying.", "High annual rainfall.", "Home to brown bears and lynxes.", "Popular spot for ziplining."],
      es: ["El nombre significa 'el que llora'.", "Alta cantidad de precipitación anual.", "Hogar de osos pardos y linces.", "Popular para practicar tirolesa."],
      pt: ["O nome significa 'o que chora'.", "Elevada pluviosidade anual.", "Lar de ursos pardos e lincos.", "Popular para a prática de ziplining."],
