    description: { de: "Der Nationalpark im Osten Georgiens bietet eine savannenartige Landschaft mit bizarren Felsformationen und Schlammvulkanen. Er ist ein wichtiger Zufluchtsort für seltene Tierarten.", hu: "Kelet-Grúzia nemzeti parkja szavannaszerű tájat, bizarr sziklaalakzatokat és iszapvulkánokat kínál. Ritka állatfajok fontos menedékhelye.", ro: "Parcul național din estul Georgiei oferă un peisaj de savană cu formațiuni stâncoase bizare și vulcani noroioși. Este un refugiu important pentru speciile rare de animale.", en: "The national park in eastern Georgia offers a savanna-like landscape with bizarre rock formations and mud volcanoes. It is an important refuge for rare animal species." , es: "El parque nacional en el este de Georgia ofrece un paisaje tipo sabana con extrañas formaciones rocosas y volcanes de lodo. Es un refugio importante para especies animales raras.", pt: "O parque nacional no leste da Geórgia oferece uma paisagem tipo savana com estranhas formações rochosas e vulcões de lama. É um refúgio importante para espécies animais raras.", fr: "Le parc national de l'est de la Géorgie offre un paysage de type savane avec des formations rocheuses bizarres et des volcans de boue. C'est un refuge important pour les espèces animales rares."},
