      hu: ["A Szovjetunió első delfináriuma (1975).", "A modernizált újranyitás 2011-ben történt.", "700 néző befogadására alkalmas.", "Az előadások 3 nyelven zajlanak.", "Delfinterápiás kezeléseket is nyújt.", "A Május 6. park területén található."],
