      en: ["First dolphinarium in the USSR (opened 1975).", "Completely modernized and reopened in 2011.", "Seating capacity for 700 spectators.", "Performances in Georgian, English, and Russian.", "Provides dolphin-assisted therapy sessions.", "Located within the 6 May Park complex."],
      es: ["Primer delfinario de la URSS (1975).", "Reapertura tras modernización en 2011.", "Capacidad para 700 espectadores.", "Espectáculos en georgiano, inglés y ruso.", "Ofrece terapia especial con delfines.", "Ubicado en el parque del 6 de mayo."],
